"use strict";

// Renders actual authenticated MVC TestServer HTML in Chromium with the app's
// real public styles/scripts. Fixtures are generated by the .NET MVC tests and
// contain deterministic fake farms only. No production database or credentials.
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { chromium } = require("playwright");
const AxeBuilder = require("@axe-core/playwright").default;

const base = process.env.SMARTFARM_BROWSER_BASE_URL || "http://127.0.0.1:5082";
const fixtures = path.join(__dirname, "authenticated-fixtures");
const screenshots = path.join(__dirname, "screenshots", "authenticated");
const screens = [
    ["farms-empty", "/Farms"],
    ["farms-populated", "/Farms"],
    ["farms-pending", "/Farms"],
    ["farms-worker", "/Farms"],
    ["farm-create", "/Farms/Create"],
    ["farm-edit", "/Farms/Edit?id=123"],
    ["farm-detail-new", "/Farms/Details?id=123"],
    ["farm-detail-worker", "/Farms/Details?id=123"],
    ["dashboard-owner", "/Dashboard?farmId=123"],
    ["dashboard-manager", "/Dashboard?farmId=123"],
    ["dashboard-worker", "/Dashboard?farmId=123"],
    ["dashboard-multiple-crops", "/Dashboard?farmId=123"],
    ["dashboard-empty", "/Dashboard?farmId=123"],
    ["12d-farm-owner", "/Farms/Details?id=123"],
    ["12d-plots-owner", "/PlotLayout?farmId=123"],
    ["12d-plots-worker", "/PlotLayout?farmId=123"],
    ["12d-crops-owner", "/Crops?farmId=123"],
    ["12d-crops-worker", "/Crops?farmId=123"],
    ["12d-edit-plot", "/Farms/EditPlot?id=123&plotId=123"],
    ["12d-edit-plan", "/Crops/EditPlan?farmId=123&cycleId=123"]
];
const widths = [320, 375, 768, 1024, 1440];

(async () => {
    fs.mkdirSync(screenshots, { recursive: true });
    for (const [name] of screens) assert.ok(fs.existsSync(path.join(fixtures, name + ".html")),
        "Missing authenticated MVC fixture: " + name);

    const browser = await chromium.launch({ headless: true });
    let captured = 0;
    try {
        for (const mode of ["light", "dark"]) {
            const context = await browser.newContext({ colorScheme: "light", reducedMotion: "reduce" });
            await context.addInitScript(value => localStorage.setItem("anigo-color-mode", value), mode);
            const page = await context.newPage();
            const errors = [];
            page.on("pageerror", e => errors.push(e.message));
            let selected = "";
            await page.route(/\/(?:Farms(?:\/|\?|$)|Dashboard(?:\?|$)|PlotLayout(?:\?|$)|Crops(?:\/|\?|$))/, async route => {
                const file = path.join(fixtures, selected + ".html");
                await route.fulfill({ status: 200, contentType: "text/html; charset=utf-8", body: fs.readFileSync(file) });
            });
            for (const width of widths) {
                await page.setViewportSize({ width, height: 900 });
                for (const [name, route] of screens) {
                    selected = name;
                    const response = await page.goto(new URL(route, base).href, { waitUntil: "networkidle" });
                    assert.equal(response?.status(), 200, name + ": server-rendered fixture");
                    assert.equal(await page.locator("main#main-content").count(), 1, name + ": main landmark");
                    assert.equal(await page.locator("html").getAttribute("data-color-mode"), mode);
                    await page.evaluate(() => document.fonts.ready);
                    const measures = await page.evaluate(() => ({
                        content: document.documentElement.scrollWidth,
                        window: innerWidth,
                        unlabeled: [...document.querySelectorAll("main button, main a[href]")].filter(el => {
                            const b = el.getBoundingClientRect();
                            return b.width && b.height &&
                                !(el.textContent?.trim() || el.getAttribute("aria-label") || el.getAttribute("title"));
                        }).length
                    }));
                    assert.ok(measures.content <= measures.window + 2,
                        name + " " + width + ": horizontal overflow " + measures.content + " > " + measures.window);
                    assert.equal(measures.unlabeled, 0, name + ": unlabeled interactive controls");
                    if (name === "farms-empty") {
                        assert.equal(await page.getByText("No farms yet").count(), 1);
                        assert.equal(await page.locator("#join-farm").count(), 1);
                    }
                    if (name === "farms-populated")
                        assert.ok(await page.locator(".ani-entry-farm-card").count() >= 2);
                    if (name === "farms-pending")
                        assert.ok(await page.getByText("Waiting for the farm owner's approval.").count() >= 1);
                    if (name === "farm-create" || name === "farm-edit") {
                        assert.ok(await page.locator("input[name='Name'], input[name='Input.Name']").count() >= 1);
                        assert.equal(await page.locator("details").first().evaluate(el => el.open), false);
                    }
                    if (name === "farm-detail-worker")
                        assert.equal(await page.locator("#add-plot").count(), 0);
                    if (name === "12d-farm-owner") {
                        assert.equal(await page.locator(".ani12d-farm-summary").count(), 1);
                        assert.equal(await page.locator(".ani12d-plots-panel").count(), 1);
                        assert.equal(await page.locator("#add-plot").count(), 1);
                        assert.equal(await page.locator(".ani12d-danger-options").count(), 1);
                    }
                    if (name === "12d-plots-owner" || name === "12d-plots-worker") {
                        assert.equal(await page.locator(".ani12d-plot-directory .ani12d-plot-card").count(), 2);
                        assert.equal(await page.locator(".ani12d-plot-disclaimer").count(), 1);
                    }
                    if (name === "12d-crops-owner" || name === "12d-crops-worker") {
                        assert.equal(await page.locator(".ani12d-calendar").count(), 1);
                        assert.equal(await page.locator(".ani12d-agenda-details[open]").count(), 1);
                        const visible = await page.locator(".ani12d-agenda-list").isVisible();
                        assert.ok(visible, "Calendar schedule must be readable by default");
                        if (width <= 375)
                            assert.equal(await page.locator(".ani12d-calendar-month").isVisible(), false,
                                "On phones the agenda replaces the cramped month grid");
                        if (name === "12d-crops-owner") {
                            assert.equal(await page.locator("#plotId option[value='']").count(), 1);
                            assert.equal(await page.locator("#plotId").inputValue(), "",
                                "Must choose plot explicitly");
                        } else {
                            assert.equal(await page.locator('button:has-text("Save planting plan")').count(), 0);
                            assert.equal(await page.locator("#planting-plans-heading").count(), 0,
                                "Workers should not see unavailable planning steps");
                        }
                    }
                    if (name === "12d-edit-plan" || name === "12d-edit-plot") {
                        assert.equal(await page.locator(".ani12d-edit-form").count(), 1);
                        assert.equal(await page.locator(".ani12d-form-actions").count(), 1);
                    }
                    if (name.startsWith("dashboard-")) {
                        assert.equal(await page.locator(".ani12c-farm-dashboard").count(), 1);
                        assert.equal(await page.locator(".ani12c-dashboard-rail").count(), 1);
                        assert.equal(await page.locator(".ani12c-metrics > a").count(), 4,
                            "Dashboard must show exactly four first-level metrics");
                        assert.equal(await page.getByRole("heading", { name: "Today's priorities" }).count(), 1);
                    }
                    if (name === "dashboard-owner") {
                        assert.equal(await page.locator(".ani12c-role-owner").count(), 1);
                        assert.equal(await page.locator(".ani12c-owner-decisions > a").count(), 3);
                    }
                    if (name === "dashboard-manager")
                        assert.equal(await page.locator(".ani12c-role-manager").count(), 1);
                    if (name === "dashboard-worker" || name === "dashboard-empty") {
                        assert.equal(await page.locator(".ani12c-role-worker").count(), 1);
                        assert.equal(await page.getByRole("heading", { name: "Your assigned work" }).count(), 1);
                        assert.equal(await page.locator(".ani12c-owner-decisions").count(), 0);
                    }
                    if (name === "dashboard-multiple-crops") {
                        assert.equal(await page.locator("#ani12c-crop-picker").count(), 1);
                        assert.equal(await page.locator(".ani12c-crop-list > li").count(), 2);
                        const hero = page.locator(".ani12c-dashboard-hero");
                        assert.equal(await hero.locator('a[href*="cycleId"]').count(), 0);
                    }
                    if (width === 375 || width === 1440) {
                        const audit = await new AxeBuilder({ page })
                            .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa"]).analyze();
                        const blocking = audit.violations.filter(v => ["serious", "critical"].includes(v.impact));
                        assert.deepEqual(blocking.map(v => v.id + ": " + v.nodes.map(n => n.target.join(" ")).join(",")),
                            [], name + " " + mode + " " + width + ": blocking accessibility issues");
                    }
                    await page.screenshot({ path: path.join(screenshots, name + "-" + mode + "-" + width + ".png"),
                        fullPage: true, animations: "disabled" });
                    captured++;
                }
            }
            assert.deepEqual(errors, [], "JavaScript errors in " + mode);
            await context.close();
        }
    } finally {
        await browser.close();
    }
    assert.equal(captured, screens.length * widths.length * 2);
    console.log("PASS: " + captured + " authenticated farm screenshots, role states, mobile widths, and accessibility scans.");
})().catch(error => { console.error(error.stack || error); process.exitCode = 1; });
